# Import the stable updater catalog during initial authoring; maintained host map afterwards.
dictionary=root/'languages/dictionary.json'
if dictionary.exists():
 saved=json.loads(dictionary.read_text());translations.update(saved['de_DE']);formal.update(saved['de_DE_formal'])
strings=set()
for p in list((root/'includes').glob('class-*.php'))+[(root/'includes/updater-translations.php')]:
 strings.update(x.replace("\\'", "'") for x in re.findall(r"(?:__|esc_html__|esc_attr__)\(\s*'((?:\\'|[^'])*)',\s*'oxygen-quicknav'",p.read_text()))
missing=strings-set(translations)
if missing:raise SystemExit('Missing host translations: '+repr(sorted(missing)))
quote=lambda s:json.dumps(s,ensure_ascii=False)
header='msgid ""\nmsgstr ""\n"Project-Id-Version: Oxygen QuickNav 2.0.0-rc.1\\n"\n"Content-Type: text/plain; charset=UTF-8\\n"\n"Content-Transfer-Encoding: 8bit\\n"\n"MIME-Version: 1.0\\n"\n"PO-Revision-Date: 2026-10-07 22:00+0000\\n"\n"Last-Translator: David Decker – DECKERWEB\\n"\n"Language-Team: German\\n"\n'
for lang in ['de_DE','de_DE_formal']:
 mapping=dict(translations)
 if lang=='de_DE_formal':mapping.update(formal)
 body=header+'"Language: '+lang+'\\n"\n"Plural-Forms: nplurals=2; plural=(n != 1);\\n"\n\n'+'\n\n'.join('msgid '+quote(s)+'\nmsgstr '+quote(mapping[s]) for s in sorted(strings))+'\n'
 path=root/'languages'/('oxygen-quicknav-'+lang+'.po');path.write_text(body)
 subprocess.run(['msgfmt','--check','-o',str(path.with_suffix('.mo')),str(path)],check=True)
(root/'languages/oxygen-quicknav.pot').write_text(header+'\n'+'\n\n'.join('msgid '+quote(s)+'\nmsgstr ""' for s in sorted(strings))+'\n')
dictionary.write_text(json.dumps({'de_DE':translations,'de_DE_formal':formal},ensure_ascii=False,indent=2)+'\n')
print(str(len(strings))+' host messages translated; bundled Library catalogs retain the host domain.')
